/* @lc app=leetcode id=3733 lang=kotlin */ class Solution { fun g(a: Long, b: Long): Long = if (b == 0L) a else g(b, a % b) fun minimumTime(d: IntArray, r: IntArray): Long = (r[0].toLong() / g(r[0].toLong(), r[1].toLong()) * r[1]).let { l -> generateSequence(1L to 100_000_000_000_000L) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { t -> if (d[0] <= t - t / r[0] && d[1] <= t - t / r[1] && d[0].toLong() + d[1] <= t - t / l) lo to t else t + 1 to hi } }.last().first } }